(()=>{
const $=id=>document.getElementById(id),L=LayoutLab,P=LayoutPLC;let rows=[],layout,index,onChange;
const units=Array.from({length:8},(_,i)=>'T'+(i+1)).concat(Array.from({length:8},(_,i)=>'C'+(i+1))),memory=Array.from({length:16},(_,i)=>'M'+(i+1));
const options=(values,value)=>values.map(t=>`<option value="${t}" ${t===value?'selected':''}>${t||'Choose output'}</option>`).join('');
function tags(){return [...Object.keys(L.inputs(layout,L.fresh(layout))),...L.outputs(layout),...memory,...units.map(u=>u+'_DONE'),...units.filter(u=>u[0]==='T').map(u=>u+'_TIMING')];}
function persist(){try{localStorage.setItem('plcquest.layout.program.v1.'+index,JSON.stringify(rows));$('programSaved').textContent='Program saved in this browser.';}catch{$('programSaved').textContent='Browser storage unavailable. Keep this tab open to retain your program.';}}
function change(){persist();onChange();render();}
function render(){const choices=['EMPTY',...tags().flatMap(t=>[t,'!'+t])];$('rungs').innerHTML=rows.length?rows.map((r,i)=>{const timed=['TON','RTO','CTU','RES'].includes(r.type),targets=r.type==='CTU'?units.filter(x=>x[0]==='C'):['TON','RTO'].includes(r.type)?units.filter(x=>x[0]==='T'):r.type==='RES'?units:[...L.outputs(layout),...memory];return `<article class="plc-rung" data-rung="${i}"><div class="rung-tools"><b>Rung ${i+1}</b><button data-action="up" ${i===0?'disabled':''} aria-label="Move rung ${i+1} up">↑</button><button data-action="down" ${i===rows.length-1?'disabled':''} aria-label="Move rung ${i+1} down">↓</button><button data-action="remove">Delete rung</button><span class="rung-power" id="rungPower${i}">OFF</span></div><div class="rung-circuit"><span class="rail">┃</span>${r.groups.map((g,j)=>`<div class="plc-group">${g.map((t,k)=>`<label class="plc-contact"><span>${t[0]==='!'?'|/|':'| |'}</span><select data-group="${j}" data-contact="${k}" aria-label="Rung ${i+1} group ${j+1} contact ${k+1}">${options(choices,t)}</select><button data-action="deleteContact" data-group="${j}" data-contact="${k}" aria-label="Remove contact">×</button></label>`).join('')}<button data-action="parallel" data-group="${j}" ${g.length>=4?'disabled':''}>+ OR branch</button></div><span class="wire">─</span>`).join('')}<button data-action="series" ${r.groups.length>=8?'disabled':''}>+ AND contact</button><div class="plc-output"><label>Instruction<select data-field="type">${options(['OTE','OTL','OTU','TON','RTO','CTU','RES'],r.type)}</select></label><label>Output / unit<select data-field="out">${options(['',...targets],r.out)}</select></label>${timed&&r.type!=='RES'?`<label>Preset (${r.type==='CTU'?'count':'seconds'})<input data-field="preset" type="number" min="0.1" max="999" step="0.1" value="${r.preset}"></label>`:''}</div><span class="rail">┃</span></div></article>`;}).join(''):'<div class="empty-program"><h3>Your PLC is empty.</h3><p>The layout is equipment only. Add your first rung to start programming it. Outputs stay off until your logic energizes them.</p></div>';$('addRung').disabled=rows.length>=64;}
$('rungs').onchange=e=>{const el=e.target,box=el.closest('[data-rung]');if(!box)return;const r=rows[Number(box.dataset.rung)];if(el.dataset.field){const field=el.dataset.field;r[field]=field==='preset'?Math.max(.1,Math.min(999,Number(el.value)||1)):el.value;if(field==='type')r.out='';}else if(el.dataset.contact!==undefined)r.groups[Number(el.dataset.group)][Number(el.dataset.contact)]=el.value;change();};
$('rungs').onclick=e=>{const b=e.target.closest('button[data-action]'),el=b?.closest('[data-rung]');if(!el)return;const i=Number(el.dataset.rung),r=rows[i],g=Number(b.dataset.group),k=Number(b.dataset.contact);switch(b.dataset.action){case 'up':if(i>0)[rows[i-1],rows[i]]=[rows[i],rows[i-1]];break;case 'down':if(i<rows.length-1)[rows[i+1],rows[i]]=[rows[i],rows[i+1]];break;case 'remove':rows.splice(i,1);break;case 'series':if(r.groups.length<8)r.groups.push(['EMPTY']);break;case 'parallel':if(r.groups[g].length<4)r.groups[g].push('EMPTY');break;case 'deleteContact':r.groups[g].splice(k,1);if(!r.groups[g].length)r.groups.splice(g,1);if(!r.groups.length)r.groups=[['EMPTY']];break;}change();};
$('addRung').onclick=()=>{if(rows.length<64){rows.push(P.blank());change();}};
window.FloorEditor={open(l,i,callback){layout=l;index=i;onChange=callback;rows=[];try{const v=JSON.parse(localStorage.getItem('plcquest.layout.program.v1.'+i)||'[]');rows=P.validate(v,l);}catch{}render();$('programSaved').textContent=rows.length?'Saved program restored.':'New floor. Start with an empty program.';$('tagList').textContent=tags().join(' · ');},rows:()=>rows,live(plc){for(let i=0;i<rows.length;i++){const el=$('rungPower'+i);if(el){const on=!!plc.trace[i]?.power;el.textContent=on?'POWER':'OFF';el.classList.toggle('powered',on);}}$('plcValues').textContent=Object.entries(plc.timers).map(([k,v])=>`${k}: ${(v.elapsed/1000).toFixed(1)} s`).concat(Object.entries(plc.counters).map(([k,v])=>`${k}: ${v.count} counts`)).join(' · ');}};
})();
